INSERT INTO `companies` VALUES (7,'Rikkeisoft',24,0,'2026-11-12 12:14:21','rikkeisoft',NULL,NULL,'Rikkeisoft là công ty công nghệ thông tin hàng đầu Việt Nam, chuyên cung cấp các giải pháp phần mềm, chuyển đổi số và phát triển dịch vụ công nghệ chất lượng cao cho thị trường quốc tế.',1,'1.000+ nhân viên','https://rikkeisoft.com','Tòa nhà Handico, Phạm Hùng, Nam Từ Liêm, Hà Nội',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENDING','2026-11-18 02:19:56','removed',96,'2026-11-17 19:19:00','chua_xac_minh'),(8,'VNG Corporation',25,0,'2026-11-12 12:14:21','vng-corporation',NULL,NULL,'VNG là doanh nghiệp công nghệ hàng đầu Việt Nam với hệ sinh thái sản phẩm phong phú gồm Zalo, ZaloPay, Zing MP3 và các nền tảng trò chơi trực tuyến toàn cầu.',1,'2.000+ nhân viên','https://vng.com.vn','Z06 Đường số 13, Tân Thuận Đông, Quận 7, TP. Hồ Chí Minh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENDING','2026-11-16 17:43:32','missing',NULL,NULL,'chua_xac_minh'),(9,'FPT Software',26,0,'2026-11-12 12:14:21','fpt-software',NULL,NULL,'FPT Software là công ty thành viên của Tập đoàn FPT, nhà cung cấp dịch vụ công nghệ thông tin và chuyển đổi số đẳng cấp thế giới với mạng lưới văn phòng tại 30 quốc gia.',1,'30.000+ nhân viên','https://fptsoftware.com','Tòa nhà FPT Cầu Giấy, 17 Duy Tân, Cầu Giấy, Hà Nội',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENDING','2026-11-16 17:43:32','missing',NULL,NULL,'chua_xac_minh'),(10,'Viettel Solutions',28,0,'2026-11-12 12:14:21','viettel-solutions',NULL,NULL,'Tổng công ty Giải pháp Doanh nghiệp Viettel (Viettel Solutions) là đơn vị tiên phong dẫn dắt chuyển đổi số cho Chính phủ, các bộ ngành, doanh nghiệp và cộng đồng xã hội.',4,'5.000+ nhân viên','https://viettelsolutions.vn','Tòa nhà Viettel, Số 1 Trần Hữu Dực, Nam Từ Liêm, Hà Nội',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENDING','2026-11-16 17:43:32','missing',NULL,NULL,'chua_xac_minh'),(11,'MoMo (M-Service)',24,0,'2026-11-12 12:14:21','momo',NULL,NULL,'MoMo là siêu ứng dụng thanh toán và tài chính số hàng đầu Việt Nam, cung cấp trải nghiệm thanh toán một chạm nhanh chóng, an toàn và tiện lợi cho hơn 30 triệu người dùng.',1,'1.500+ nhân viên','https://momo.vn','Tòa nhà Phú Mỹ Hưng, Hoàng Văn Thái, Tân Phú, Quận 7, TP. Hồ Chí Minh',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENDING','2026-11-16 17:43:32','missing',NULL,NULL,'chua_xac_minh'),(12,'VNPT IT',25,0,'2026-11-12 12:14:21','vnpt-it',NULL,NULL,'Công ty Công nghệ thông tin VNPT (VNPT-IT) là đơn vị trụ cột của Tập đoàn VNPT trong nghiên cứu, phát triển và triển khai các sản phẩm, giải pháp công nghệ thông tin phục vụ chuyển đổi số quốc gia.',4,'3.000+ nhân viên','https://vnptit.vn','57 Huỳnh Thúc Kháng, Đống Đa, Hà Nội',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'PENDING','2026-11-16 17:43:32','missing',NULL,NULL,'chua_xac_minh');
