INSERT INTO `cv_documents` VALUES (5,29,'CV Ứng tuyển IT','simple','{\"full_name\":\"Nguyễn Thành Long\",\"headline\":\"Kỹ sư Phát triển Frontend (React / Vue / TypeScript)\",\"email\":\"thanhlong.dev@gmail.com\",\"phone\":\"0987 654 321\",\"location\":\"Cầu Giấy, Hà Nội\",\"linkedin_url\":\"https://linkedin.com/in/thanhlong-dev\",\"github_url\":\"https://github.com/thanhlong-tech\",\"portfolio_url\":\"https://thanhlong.dev\",\"bio\":\"Lập trình viên Frontend với hơn 4 năm kinh nghiệm xây dựng ứng dụng web quy mô lớn bằng React, TypeScript và Next.js. Đam mê tối ưu hóa hiệu năng trải nghiệm người dùng (Core Web Vitals), thiết kế Design System nhất quán và tuân thủ các tiêu chuẩn trợ năng WCAG. Khả năng làm việc nhóm tốt, tư duy phản biện và sẵn sàng tiếp cận công nghệ mới.\",\"skills\":[\"JavaScript (ES6+)\",\"TypeScript\",\"React.js\",\"Next.js\",\"Vue.js\",\"HTML5/CSS3/Sass\",\"Tailwind CSS\",\"Redux Toolkit / Zustand\",\"RESTful API & GraphQL\",\"Jest & Playwright\",\"Git & CI/CD GitHub Actions\",\"Webpack / Vite\"],\"experiences\":[{\"title\":\"Senior Frontend Engineer\",\"company\":\"Công ty Cổ phần Công nghệ Rikkei Digital\",\"start_month\":\"2023-03\",\"end_month\":\"\",\"is_current\":true,\"description\":\"- Chủ trì thiết kế và triển khai kiến trúc vi dịch vụ (Microservices) chịu tải cao với hơn 2.000.000 yêu cầu mỗi ngày tại hệ thống đợt 1.\\n- Tối ưu hóa truy vấn cơ sở dữ liệu MySQL, áp dụng chỉ mục B-Tree và Redis Caching giúp giảm 65% độ trễ phản hồi máy chủ API (p99 latency < 80ms).\\n- Xây dựng hệ thống giám sát phân tán sử dụng Prometheus, Grafana và OpenTelemetry, nâng cao chỉ số sẵn sàng hệ thống (SLA) lên 99.98%.\\n- Hướng dẫn và dẫn dắt đội ngũ kỹ sư 12 thành viên, tổ chức các buổi Tech Sharing định kỳ về Clean Architecture, Design Patterns và TDD.\\n- Trực tiếp cấu hình pipeline CI/CD tự động hoá với Docker, Kubernetes và GitHub Actions, rút ngắn thời gian deploy từ 45 phút xuống dưới 8 phút.\"},{\"title\":\"Frontend Developer\",\"company\":\"VNPAY Solution JSC\",\"start_month\":\"2021-01\",\"end_month\":\"2023-02\",\"is_current\":false,\"description\":\"- Chủ trì thiết kế và triển khai kiến trúc vi dịch vụ (Microservices) chịu tải cao với hơn 2.000.000 yêu cầu mỗi ngày tại hệ thống đợt 2.\\n- Tối ưu hóa truy vấn cơ sở dữ liệu MySQL, áp dụng chỉ mục B-Tree và Redis Caching giúp giảm 65% độ trễ phản hồi máy chủ API (p99 latency < 80ms).\\n- Xây dựng hệ thống giám sát phân tán sử dụng Prometheus, Grafana và OpenTelemetry, nâng cao chỉ số sẵn sàng hệ thống (SLA) lên 99.98%.\\n- Hướng dẫn và dẫn dắt đội ngũ kỹ sư 12 thành viên, tổ chức các buổi Tech Sharing định kỳ về Clean Architecture, Design Patterns và TDD.\\n- Trực tiếp cấu hình pipeline CI/CD tự động hoá với Docker, Kubernetes và GitHub Actions, rút ngắn thời gian deploy từ 45 phút xuống dưới 8 phút.\"},{\"title\":\"Junior Web Developer\",\"company\":\"FPT Software Hà Nội\",\"start_month\":\"2019-09\",\"end_month\":\"2020-12\",\"is_current\":false,\"description\":\"- Chủ trì thiết kế và triển khai kiến trúc vi dịch vụ (Microservices) chịu tải cao với hơn 2.000.000 yêu cầu mỗi ngày tại hệ thống đợt 3.\\n- Tối ưu hóa truy vấn cơ sở dữ liệu MySQL, áp dụng chỉ mục B-Tree và Redis Caching giúp giảm 65% độ trễ phản hồi máy chủ API (p99 latency < 80ms).\\n- Xây dựng hệ thống giám sát phân tán sử dụng Prometheus, Grafana và OpenTelemetry, nâng cao chỉ số sẵn sàng hệ thống (SLA) lên 99.98%.\\n- Hướng dẫn và dẫn dắt đội ngũ kỹ sư 12 thành viên, tổ chức các buổi Tech Sharing định kỳ về Clean Architecture, Design Patterns và TDD.\\n- Trực tiếp cấu hình pipeline CI/CD tự động hoá với Docker, Kubernetes và GitHub Actions, rút ngắn thời gian deploy từ 45 phút xuống dưới 8 phút.\"},{\"title\":\"\",\"company\":\"\",\"start_month\":\"\",\"end_month\":\"\",\"description\":\"- Chủ trì thiết kế và triển khai kiến trúc vi dịch vụ (Microservices) chịu tải cao với hơn 2.000.000 yêu cầu mỗi ngày tại hệ thống đợt 4.\\n- Tối ưu hóa truy vấn cơ sở dữ liệu MySQL, áp dụng chỉ mục B-Tree và Redis Caching giúp giảm 65% độ trễ phản hồi máy chủ API (p99 latency < 80ms).\\n- Xây dựng hệ thống giám sát phân tán sử dụng Prometheus, Grafana và OpenTelemetry, nâng cao chỉ số sẵn sàng hệ thống (SLA) lên 99.98%.\\n- Hướng dẫn và dẫn dắt đội ngũ kỹ sư 12 thành viên, tổ chức các buổi Tech Sharing định kỳ về Clean Architecture, Design Patterns và TDD.\\n- Trực tiếp cấu hình pipeline CI/CD tự động hoá với Docker, Kubernetes và GitHub Actions, rút ngắn thời gian deploy từ 45 phút xuống dưới 8 phút.\"}],\"educations\":[{\"school\":\"Đại học Bách Khoa Hà Nội\",\"major\":\"Công nghệ Thông tin (Chương trình Tiên tiến)\",\"degree\":\"Kỹ sư\",\"start_year\":\"2015\",\"end_year\":\"2020\",\"description\":\"Tốt nghiệp loại Giỏi (GPA 3.45/4.0). Đạt học bổng khuyến khích học tập 3 kỳ liên tiếp. Giải Ba cuộc thi Sáng tạo Công nghệ Sinh viên năm 2019.\"}]}',1,'2026-11-15 21:35:21','2026-11-15 21:35:21');
